/**
 * Imports
 */

import { z as zod } from "zod";

/**
 * Create a zod enum schema from a const object (mostly coming from orval generated code).
 *
 * This helps us to create a zod enum from a const object like this, which mainly is generated by orval from
 * kotlin enum classes:
 *
 * const ChickenBreed = {
 *   Silkie: 'Silkie',
 *   RhodeIslandRed: 'RhodeIslandRed',
 *   AyamCemani: 'AyamCemani',
 *   Leghorn: 'Leghorn',
 *   Orpington: 'Orpington',
 * } as const;
 *
 * When only doing it like this `Object.values(ChickenBreed)` the resulting type looks like this:
 * `("Silkie" | "RhodeIslandRed" | "AyamCemani" | "Leghorn" | "Orpington")[]`
 *
 * But zod expects a tuple of string literals: ["Silkie", "RhodeIslandRed", "AyamCemani", "Leghorn", "Orpington"]
 * So a somewhat complex typecast is necessary, which is why we created this helper function.
 */

export function createZodEnumFromConstObject<T extends Record<string, string>>(obj: T) {
  return zod.enum(Object.values(obj) as [T[keyof T]]);
}
